-- Stage6: report/repertoire tables plus optional structured fields on old submission/comment rows. No old field or row is rewritten.
CREATE TABLE growth_repertoire(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('learning','done')),start_date TEXT,completed_date TEXT,image_ids_json TEXT NOT NULL DEFAULT '[]',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE INDEX growth_repertoire_student ON growth_repertoire(tenant_id,student_id,status,completed_date);
-- Structured personal snapshots extend the existing submission/comment rows.
-- growth_feedback is only a repo compatibility VIEW, never a separate feedback table/workflow.
ALTER TABLE lesson_submissions ADD COLUMN personal_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(personal_json));
ALTER TABLE lesson_comments ADD COLUMN feedback_versions_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(feedback_versions_json));
CREATE TABLE growth_feedback_copies(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,feedback_id TEXT,submission_id TEXT,student_id TEXT NOT NULL,actor_id TEXT NOT NULL,copied_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE VIEW growth_feedback AS SELECT r.tenant_id,json_extract(j.value,'$.id') id,r.lesson_id,r.id submission_id,json_extract(j.value,'$.student_id') student_id,json_extract(j.value,'$.seq') seq,json_extract(j.value,'$.doc_json') doc_json,json_extract(j.value,'$.status') status,json_extract(j.value,'$.confirmed_at') confirmed_at,json_extract(j.value,'$.created_at') created_at,json_extract(j.value,'$.created_by') created_by,json_extract(j.value,'$.updated_at') updated_at,json_extract(j.value,'$.updated_by') updated_by,json_extract(j.value,'$.version') version,json_extract(j.value,'$.deleted_at') deleted_at FROM lesson_submissions r,json_each(r.personal_json) j UNION ALL SELECT r.tenant_id,json_extract(j.value,'$.id') id,r.lesson_id,NULL submission_id,json_extract(j.value,'$.student_id') student_id,json_extract(j.value,'$.seq') seq,json_extract(j.value,'$.doc_json') doc_json,json_extract(j.value,'$.status') status,json_extract(j.value,'$.confirmed_at') confirmed_at,json_extract(j.value,'$.created_at') created_at,json_extract(j.value,'$.created_by') created_by,json_extract(j.value,'$.updated_at') updated_at,json_extract(j.value,'$.updated_by') updated_by,json_extract(j.value,'$.version') version,json_extract(j.value,'$.deleted_at') deleted_at FROM lesson_comments r,json_each(r.feedback_versions_json) j;
CREATE TRIGGER growth_feedback_insert INSTEAD OF INSERT ON growth_feedback BEGIN
 SELECT CASE WHEN NEW.submission_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lesson_submissions WHERE tenant_id=NEW.tenant_id AND id=NEW.submission_id AND lesson_id=NEW.lesson_id) THEN RAISE(ABORT,'invalid_feedback_submission') END;
 SELECT CASE WHEN NEW.submission_id IS NULL AND NOT EXISTS(SELECT 1 FROM lesson_comments WHERE tenant_id=NEW.tenant_id AND lesson_id=NEW.lesson_id AND student_id=NEW.student_id) THEN RAISE(ABORT,'invalid_feedback_comment') END;
 UPDATE lesson_submissions SET personal_json=json_insert(personal_json,'$[#]',json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at)) WHERE tenant_id=NEW.tenant_id AND id=NEW.submission_id;
 UPDATE lesson_comments SET feedback_versions_json=json_insert(feedback_versions_json,'$[#]',json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at)) WHERE tenant_id=NEW.tenant_id AND lesson_id=NEW.lesson_id AND student_id=NEW.student_id AND NEW.submission_id IS NULL;
END;
CREATE TRIGGER growth_feedback_update INSTEAD OF UPDATE ON growth_feedback BEGIN
 SELECT CASE WHEN OLD.status='confirmed' THEN RAISE(ABORT,'growth_feedback_immutable') END;
 UPDATE lesson_submissions SET personal_json=(SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')=OLD.id THEN json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at) ELSE value END)) FROM json_each(personal_json)) WHERE tenant_id=OLD.tenant_id AND id=OLD.submission_id;
 UPDATE lesson_comments SET feedback_versions_json=(SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')=OLD.id THEN json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at) ELSE value END)) FROM json_each(feedback_versions_json)) WHERE tenant_id=OLD.tenant_id AND lesson_id=OLD.lesson_id AND student_id=OLD.student_id AND OLD.submission_id IS NULL;
END;
CREATE TABLE growth_batches(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,from_date TEXT NOT NULL,to_date TEXT NOT NULL,teacher_id TEXT,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE growth_reports(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,batch_id TEXT NOT NULL,student_id TEXT NOT NULL,teacher_id TEXT,report_class_id TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN('draft','ready','published')),progress TEXT NOT NULL CHECK(progress IN('not_started','draft','ready','published')),doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),context_json TEXT NOT NULL CHECK(json_valid(context_json)),published_revision_id TEXT,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,batch_id,student_id),FOREIGN KEY(tenant_id,batch_id) REFERENCES growth_batches(tenant_id,id));
CREATE INDEX growth_report_student ON growth_reports(tenant_id,student_id,status,teacher_id);
CREATE TABLE growth_report_revisions(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,report_id TEXT NOT NULL,seq INTEGER NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),context_json TEXT NOT NULL CHECK(json_valid(context_json)),action TEXT NOT NULL,published_at INTEGER,publication_order INTEGER,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,report_id,seq),FOREIGN KEY(tenant_id,report_id) REFERENCES growth_reports(tenant_id,id));
CREATE TRIGGER growth_revision_immutable BEFORE UPDATE ON growth_report_revisions BEGIN SELECT RAISE(ABORT,'growth_revision_immutable'); END;
CREATE TABLE growth_notifications(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,report_id TEXT NOT NULL,revision_id TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,report_id) REFERENCES growth_reports(tenant_id,id),FOREIGN KEY(tenant_id,revision_id) REFERENCES growth_report_revisions(tenant_id,id));

CREATE UNIQUE INDEX growth_publication_order ON growth_report_revisions(tenant_id,publication_order) WHERE publication_order IS NOT NULL;

-- A report/feedback-only seed keeps all existing plan/article packs and immutable versions intact.
INSERT INTO style_packs(id,name,current_version,active,scope_all,default_plan,created_at) VALUES('stp_growth_folio','成长书册','1.0.0',1,1,0,0);
INSERT INTO style_pack_versions(id,pack_id,version,manifest_json,created_at) SELECT 'sv_stp_growth_folio','stp_growth_folio','1.0.0',json_set(manifest_json,'$.id','stp_growth_folio','$.name','成长书册','$.doc_types',json('["report","feedback_card"]')),0 FROM style_pack_versions WHERE pack_id='stp_folio' AND version='1.0.0';
